package cn.fireassistant;

import com.fasterxml.jackson.databind.*;
import java.time.OffsetDateTime;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.test.web.servlet.*;
import org.springframework.transaction.annotation.Transactional;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest @AutoConfigureMockMvc @Transactional
class WorkflowTests {
    @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired JdbcTemplate jdbc;@Value("${app.demo-password}")String password;
    static final byte[] PNG=Base64.getDecoder().decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aXaAAAAAASUVORK5CYII=");
    JsonNode data(ResultActions result)throws Exception{return json.readTree(result.andReturn().getResponse().getContentAsString()).get("data");}
    String token(String name)throws Exception{return data(mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("username",name,"password",password)))).andExpect(status().isOk())).get("token").asText();}
    JsonNode write(String method,String path,String token,Map<String,Object> body,int status)throws Exception{var req=method.equals("PUT")?put(path):method.equals("PATCH")?patch(path):post(path);return data(mvc.perform(req.header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body))).andExpect(status().is(status)));}
    JsonNode detail(String id,String token)throws Exception{return data(mvc.perform(get("/api/tasks/"+id).header("Authorization","Bearer "+token)).andExpect(status().isOk()));}
    int version(String id,String token)throws Exception{return detail(id,token).get("version").asInt();}
    JsonNode action(String path,String taskId,String token,Map<String,Object> fields,int status)throws Exception{var body=new LinkedHashMap<>(fields);body.put("version",version(taskId,token));return write("POST",path,token,body,status);}
    String create(String admin,String source)throws Exception{return write("POST","/api/tasks",admin,Map.of("unitId","unit-01","source",source,"risk","高风险关注","due",OffsetDateTime.now().plusDays(1).toString(),"focus",List.of("设备核验"),"inspectorId","user-inspector","reviewerId","user-reviewer","recheckerId","user-rechecker"),200).get("id").asText();}
    List<String> inspect(String task,String officer,int abnormal)throws Exception{action("/api/tasks/"+task+"/start",task,officer,Map.of(),200);write("PUT","/api/tasks/"+task+"/site-check",officer,Map.of("version",version(task,officer),"type","学校","height",20,"floors",4,"people",300),200);List<String> items=new ArrayList<>();int index=0;for(var item:detail(task,officer).get("checklist")){String id=item.get("id").asText();items.add(id);write("PUT","/api/tasks/"+task+"/checklist/"+id,officer,Map.of("version",version(task,officer),"status",index++<abnormal?"abnormal":"normal"),200);}return items;}
    String issue(String task,String item,String officer,List<String> photos,List<String> risks)throws Exception{return action("/api/tasks/"+task+"/issues",task,officer,Map.of("itemId",item,"type","设施运行异常","location","一层检查点","finding","现场核验设备运行异常","photoIds",photos,"riskEventIds",risks),200).get("id").asText();}
    void review(String task,String issue,String reviewer,String decision)throws Exception{action("/api/issues/"+issue+"/review",task,reviewer,Map.of("decision",decision,"opinion",decision.equals("return")?"照片和事实不足，请补充":"现场问题确认","requirements","恢复设备并提交材料","responsibleContact","学校安全负责人","rectificationDue",OffsetDateTime.now().plusDays(3).toString()),200);}
    void material(String task,String issue,String officer,String content)throws Exception{action("/api/issues/"+issue+"/rectifications",task,officer,Map.of("description",content,"provider","清河实验学校","fileIds",List.of()),200);}
    @Test void phaseDTwoIssuesReturnResubmitAndImmutableReviewSnapshots()throws Exception{
        String officer=token("tianbo"),reviewer=token("zhangsan"),task=create(token("admin"),"日常抽查");var items=inspect(task,officer,2);String first=issue(task,items.get(0),officer,List.of(),List.of()),second=issue(task,items.get(1),officer,List.of(),List.of());action("/api/tasks/"+task+"/submit-review",task,officer,Map.of(),200);review(task,first,reviewer,"confirm");review(task,second,reviewer,"return");assertEquals("进行中",detail(task,officer).get("status").asText());
        write("PATCH","/api/issues/"+second,officer,Map.of("version",version(task,officer),"type","设施运行异常","location","一层检查点","finding","补充核验事实与测量结果","photoIds",List.of(),"riskEventIds",List.of()),200);action("/api/tasks/"+task+"/submit-review",task,officer,Map.of(),200);review(task,second,reviewer,"confirm");action("/api/tasks/"+task+"/review",task,reviewer,Map.of("opinion","本轮审核全部完成","excludedRiskIds",List.of()),200);var done=detail(task,reviewer);assertEquals("整改中",done.get("status").asText());assertEquals(4,done.at("/history/reviews").size());var old=done.at("/history/reviews").findValuesAsText("finding");assertTrue(old.contains("现场核验设备运行异常"));assertTrue(old.contains("补充核验事实与测量结果"));
    }
    @Test void phaseDNoProblemRequiresReviewerAndExplicitSourceDisposition()throws Exception{
        String officer=token("tianbo"),reviewer=token("zhangsan"),task=create(token("admin"),"设施异常触发");inspect(task,officer,0);action("/api/tasks/"+task+"/submit-review",task,officer,Map.of(),200);action("/api/tasks/"+task+"/close",task,officer,Map.of("opinion","自行关闭"),403);action("/api/tasks/"+task+"/review",task,reviewer,Map.of("opinion","确认无问题","excludedRiskIds",List.of()),400);String risk=detail(task,reviewer).get("events").get(0).get("id").asText();action("/api/tasks/"+task+"/review",task,reviewer,Map.of("opinion","现场核验无异常，原始提示排除","excludedRiskIds",List.of(risk)),200);assertEquals("已完成",detail(task,officer).get("status").asText());assertEquals("已排除",detail(task,officer).get("events").get(0).get("state").asText());
    }
    @Test void phaseDAttachmentValidationPersistenceAndPermissions()throws Exception{
        String officer=token("tianbo"),reviewer=token("zhangsan"),task=create(token("admin"),"日常抽查");var items=inspect(task,officer,1);var invalid=new MockMultipartFile("file","fake.png","image/png","this is not an image".getBytes());mvc.perform(multipart("/api/files/photos").file(invalid).param("taskId",task).header("Authorization","Bearer "+officer)).andExpect(status().isBadRequest());
        var photo=new MockMultipartFile("file","证据.png","image/png",PNG);String file=data(mvc.perform(multipart("/api/files/photos").file(photo).param("taskId",task).header("Authorization","Bearer "+officer)).andExpect(status().isOk())).get("id").asText();mvc.perform(get("/api/files/photos/"+file).header("Authorization","Bearer "+reviewer)).andExpect(status().isNotFound());String issue=issue(task,items.get(0),officer,List.of(file),List.of());mvc.perform(get("/api/files/photos/"+file).header("Authorization","Bearer "+reviewer)).andExpect(status().isNotFound());action("/api/tasks/"+task+"/submit-review",task,officer,Map.of(),200);mvc.perform(get("/api/files/photos/"+file).header("Authorization","Bearer "+reviewer)).andExpect(status().isOk()).andExpect(content().bytes(PNG));mvc.perform(get("/api/files/photos/"+file)).andExpect(status().isUnauthorized());mvc.perform(delete("/api/files/"+file).header("Authorization","Bearer "+officer)).andExpect(status().isForbidden());assertEquals(issue,jdbc.queryForObject("SELECT bound_id FROM file_attachment WHERE id=?",String.class,file));
        jdbc.update("INSERT INTO sys_user(id,username,password_hash,name,role,org_id) SELECT 'unassigned-inspector','unassigned-inspector',password_hash,'未分配人员','INSPECTOR',org_id FROM sys_user WHERE id='user-inspector'");mvc.perform(get("/api/files/photos/"+file).header("Authorization","Bearer "+token("unassigned-inspector"))).andExpect(status().isNotFound());
    }
    @Test void phaseEPartialClosureFailedRecheckNewMaterialAndRiskConsistency()throws Exception{
        String officer=token("tianbo"),reviewer=token("zhangsan"),rechecker=token("lisi"),task=create(token("admin"),"设施异常触发");var items=inspect(task,officer,2);String sourceRisk=detail(task,officer).get("events").get(0).get("id").asText();String first=issue(task,items.get(0),officer,List.of(),List.of(sourceRisk)),second=issue(task,items.get(1),officer,List.of(),List.of());action("/api/tasks/"+task+"/submit-review",task,officer,Map.of(),200);review(task,first,reviewer,"confirm");review(task,second,reviewer,"confirm");action("/api/tasks/"+task+"/review",task,reviewer,Map.of("opinion","问题已确认","excludedRiskIds",List.of()),200);action("/api/issues/"+first+"/recheck",task,rechecker,Map.of("conclusion","pass","finding","尚无整改材料","fileIds",List.of()),400);
        material(task,first,officer,"第一项已恢复设备");action("/api/issues/"+first+"/recheck",task,officer,Map.of("conclusion","pass","finding","越权关闭","fileIds",List.of()),403);action("/api/issues/"+first+"/recheck",task,rechecker,Map.of("conclusion","pass","finding","第一项现场复核正常","fileIds",List.of()),200);assertEquals("整改中",detail(task,rechecker).get("status").asText());assertEquals(1,detail(task,rechecker).get("events").findValuesAsText("state").stream().filter("整改中"::equals).count());
        material(task,second,officer,"第二项首次整改材料");action("/api/issues/"+second+"/recheck",task,rechecker,Map.of("conclusion","fail","finding","设备仍异常，要求继续整改","fileIds",List.of()),200);action("/api/issues/"+second+"/recheck",task,rechecker,Map.of("conclusion","pass","finding","没有新材料","fileIds",List.of()),400);material(task,second,officer,"第二项补充维修及核验材料");action("/api/issues/"+second+"/recheck",task,rechecker,Map.of("conclusion","pass","finding","第二次现场复核合格","fileIds",List.of()),200);var done=detail(task,rechecker);assertEquals("已完成",done.get("status").asText());assertEquals("高风险关注",done.get("risk").asText());assertEquals(3,done.at("/history/rechecks").size());assertEquals(3,done.at("/history/rectifications").size());assertTrue(done.get("events").findValuesAsText("state").stream().allMatch("复查合格"::equals));
        var unit=data(mvc.perform(get("/api/units/unit-01").header("Authorization","Bearer "+officer)).andExpect(status().isOk()));assertEquals(2,unit.get("events").size());
    }
}
